import { Question, CurveDiagramConfig } from "@/lib/types";

/**
 * Year 2 — Parametric Equations § 8.3 Curve Sketching
 * Ref: y2pe3
 * 71 questions: sketching parametric curves by tabulating, finding
 * intercepts, ranges, identifying conic types, and key features
 * (turning points in x, y).
 */

/**
 * Build a CurveDiagram ("mafs") config for a parametric curve x(t), y(t) over
 * a parameter range. Samples the curve into one or more polyline segments
 * (splitting at non-finite values and across asymptotes), auto-windows the
 * view (optionally with equal aspect so circles/ellipses read true), and adds
 * marked points, direction arrows and asymptote lines.
 */
function paramDiagram(
  xf: (t: number) => number,
  yf: (t: number) => number,
  tr: [number, number],
  opts: {
    equal?: boolean;
    win?: [number, number, number, number];
    pts?: Array<[number, number, string, string]>;
    arrowsAt?: number[];
    asymV?: number[];
    asymH?: number[];
    xLabel?: string;
    yLabel?: string;
    samples?: number;
  } = {},
): CurveDiagramConfig {
  const N = opts.samples ?? 260;
  const [ta, tb] = tr;
  const raw: Array<[number, number] | null> = [];
  for (let i = 0; i <= N; i++) {
    const t = ta + (tb - ta) * (i / N);
    const x = xf(t);
    const y = yf(t);
    raw.push(Number.isFinite(x) && Number.isFinite(y) ? [x, y] : null);
  }

  let xMin: number, xMax: number, yMin: number, yMax: number;
  if (opts.win) {
    [xMin, xMax, yMin, yMax] = opts.win;
  } else {
    const xs: number[] = [];
    const ys: number[] = [];
    for (const p of raw) {
      if (p) {
        xs.push(p[0]);
        ys.push(p[1]);
      }
    }
    for (const p of opts.pts ?? []) {
      xs.push(p[0]);
      ys.push(p[1]);
    }
    let dxmin = Math.min(...xs);
    let dxmax = Math.max(...xs);
    let dymin = Math.min(...ys);
    let dymax = Math.max(...ys);
    const padx = (dxmax - dxmin) * 0.12 || 1;
    const pady = (dymax - dymin) * 0.12 || 1;
    dxmin -= padx;
    dxmax += padx;
    dymin -= pady;
    dymax += pady;
    if (opts.equal) {
      const ASPECT = 456 / 308; // plot area width / height in the renderer
      const cx = (dxmin + dxmax) / 2;
      const cy = (dymin + dymax) / 2;
      let wx = dxmax - dxmin;
      let wy = dymax - dymin;
      if (wx / wy < ASPECT) wx = wy * ASPECT;
      else wy = wx / ASPECT;
      dxmin = cx - wx / 2;
      dxmax = cx + wx / 2;
      dymin = cy - wy / 2;
      dymax = cy + wy / 2;
    }
    xMin = dxmin;
    xMax = dxmax;
    yMin = dymin;
    yMax = dymax;
  }

  // Build polyline segments: clamp wild excursions and break the path at
  // non-finite points or large jumps (asymptote crossings).
  const span = Math.max(xMax - xMin, yMax - yMin);
  const yLo = yMin - (yMax - yMin);
  const yHi = yMax + (yMax - yMin);
  const jump = span * 0.5;
  const curves: NonNullable<CurveDiagramConfig["curves"]> = [];
  let seg: Array<[number, number]> = [];
  let prev: [number, number] | null = null;
  const flush = () => {
    if (seg.length > 1) curves.push({ points: seg, color: "#1d4ed8", width: 2 });
    seg = [];
  };
  for (const p of raw) {
    if (!p) {
      flush();
      prev = null;
      continue;
    }
    const cy = Math.max(yLo, Math.min(yHi, p[1]));
    const cp: [number, number] = [p[0], cy];
    if (prev && Math.abs(cp[0] - prev[0]) + Math.abs(cp[1] - prev[1]) > jump) flush();
    seg.push(cp);
    prev = cp;
  }
  flush();

  const lines: NonNullable<CurveDiagramConfig["lines"]> = [];
  for (const t of opts.arrowsAt ?? []) {
    const dt = (tb - ta) * 0.02;
    const a: [number, number] = [xf(t), yf(t)];
    const b: [number, number] = [xf(t + dt), yf(t + dt)];
    if ([a[0], a[1], b[0], b[1]].every(Number.isFinite))
      lines.push({ from: a, to: b, color: "#16a34a", arrow: true });
  }
  for (const x of opts.asymV ?? []) lines.push({ from: [x, yMin], to: [x, yMax], color: "#64748b", dashed: true });
  for (const y of opts.asymH ?? []) lines.push({ from: [xMin, y], to: [xMax, y], color: "#64748b", dashed: true });

  const points = (opts.pts ?? []).map((p) => ({
    at: [p[0], p[1]] as [number, number],
    label: p[2] || undefined,
    labelAnchor: (p[3] || "se") as NonNullable<NonNullable<CurveDiagramConfig["points"]>[number]["labelAnchor"]>,
    color: "#dc2626",
    r: 3,
  }));

  return { xMin, xMax, yMin, yMax, xLabel: opts.xLabel, yLabel: opts.yLabel, curves, lines, points };
}

